// Remove output trees that are regenerated by the next build. The caches in dist/cargo
// and the kache store are deliberately not touched: they are the build-time speed budget.
import { existsSync, lstatSync, readdirSync, rmSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const transient = [
    "dist/cargo/debug/tools",
    "dist/release/portable",
    "dist/.tools-system-build",
    "dist/dev-tools.new",
    "dist/dev-tools.old",
];

function sizeOf(path) {
    let total = 0;
    for (const entry of readdirSync(path, { withFileTypes: true })) {
        const child = resolve(path, entry.name);
        if (entry.isDirectory()) {
            total += sizeOf(child);
        } else if (entry.isFile()) {
            total += lstatSync(child).size;
        }
    }
    return total;
}

function mib(bytes) {
    return `${(bytes / 1024 / 1024).toFixed(1)} MiB`;
}

let removed = 0;
for (const relative of transient) {
    const path = resolve(root, relative);
    if (!existsSync(path)) {
        continue;
    }
    const bytes = sizeOf(path);
    rmSync(path, { recursive: true, force: true });
    removed += bytes;
    console.log(`removed ${relative} (${mib(bytes)})`);
}
console.log(`Reclaimed ${mib(removed)}. Cargo and kache artifacts were kept.`);
